import 'dart:convert';

class Deputization {
	int? id;
	int? userId;
	String? userName;
	int? idNumber;
	String? deputizationContent;
	String? status;
	DateTime? createdAt;
	DateTime? updatedAt;

	Deputization({
		this.id, 
		this.userId, 
		this.userName, 
		this.idNumber, 
		this.deputizationContent, 
		this.status, 
		this.createdAt, 
		this.updatedAt, 
	});

	factory Deputization.(Map<String, dynamic> data) {
		return Deputization(
			id: data['id'] as int?,
			userId: data['user_id'] as int?,
			userName: data['user_name'] as String?,
			idNumber: data['ID_Number'] as int?,
			deputizationContent: data['deputization_Content'] as String?,
			status: data['status'] as String?,
			createdAt: data['created_at'] == null
						? null
						: DateTime.parse(data['created_at'] as String),
			updatedAt: data['updated_at'] == null
						? null
						: DateTime.parse(data['updated_at'] as String),
		);
	}



	Map<String, dynamic> () {
		return {
			'id': id,
			'user_id': userId,
			'user_name': userName,
			'ID_Number': idNumber,
			'deputization_Content': deputizationContent,
			'status': status,
			'created_at': createdAt?.toIso8601String(),
			'updated_at': updatedAt?.toIso8601String(),		};
	}

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [Deputization].
	factory Deputization.fromJson(String data) {
		return Deputization.(json.decode(data) as Map<String, dynamic>);
	}
  /// `dart:convert`
  ///
  /// Converts [Deputization] to a JSON string.
	String toJson() => json.encode(());
}
